class _Update:
    """Tracks value changes that happen while a single update is in progress.

    An update starts when an input cell's value is set and ends once the
    change has propagated through all dependent compute cells and the
    system has reached a new stable state. Callbacks are only fired in
    ``end`` and only for cells whose value in the new stable state differs
    from their value in the previous stable state.
    """

    def __init__(self):
        self.active = False
        self.previous = {}
        self.changed = []

    def begin(self):
        self.active = True
        self.previous = {}
        self.changed = []

    def end(self):
        self.active = False
        for cell in self.changed:
            if cell._value != self.previous[cell]:
                for callback in list(cell._callbacks):
                    callback(cell._value)
        self.previous = {}
        self.changed = []


_update = _Update()


class _Cell:
    def __init__(self):
        self._value = None
        self._observers = []
        self._callbacks = []

    @property
    def value(self):
        return self._value

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

    def _change_value(self, new_value):
        if new_value == self._value:
            return
        if _update.active:
            if self not in _update.previous:
                _update.previous[self] = self._value
                _update.changed.append(self)
        self._value = new_value
        for observer in self._observers:
            observer._recompute()


class InputCell(_Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        if _update.active:
            # Nested update: just propagate; the outer update will fire
            # callbacks once the system reaches a stable state.
            self._change_value(new_value)
        else:
            _update.begin()
            try:
                self._change_value(new_value)
            finally:
                _update.end()


class ComputeCell(_Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = list(inputs)
        self._compute_function = compute_function
        for input in self._inputs:
            input._observers.append(self)
        self._recompute()

    def _recompute(self):
        new_value = self._compute_function([cell.value for cell in self._inputs])
        self._change_value(new_value)

